// Bollard UI — version-range-input · MIT licence · https://bollard-ui.vercel.app/components/version-range-input

/** A small, dependency-free implementation of npm's semver range rules (node-semver, default options). */

export interface SemVer {
  major: number
  minor: number
  patch: number
  /** Prerelease identifiers: "1.0.0-beta.2" → ["beta", 2]. */
  pre: (string | number)[]
}

type Op = ">=" | ">" | "<" | "<=" | "="
export interface Comparator {
  op: Op
  version: SemVer
}
/** All comparators must pass (AND). A range is a list of these joined by || (OR). */
export type ComparatorSet = Comparator[]

const NR = "0|[1-9]\\d*"
const PART = "[0-9A-Za-z-]+"
const VERSION = new RegExp(`^v?(${NR})\\.(${NR})\\.(${NR})(?:-(${PART}(?:\\.${PART})*))?(?:\\+${PART}(?:\\.${PART})*)?$`)
const PARTIAL = new RegExp(
  `^v?(${NR}|[xX*])(?:\\.(${NR}|[xX*])(?:\\.(${NR}|[xX*])(?:-(${PART}(?:\\.${PART})*))?(?:\\+${PART}(?:\\.${PART})*)?)?)?$`,
)

const toPre = (text?: string) => (text ? text.split(".").map((id) => (/^\d+$/.test(id) ? Number(id) : id)) : [])

/** Parses a full version such as "1.2.3" or "2.0.0-rc.1", or returns null. */
export function parseVersion(text: string): SemVer | null {
  const m = VERSION.exec(text.trim())
  return m ? { major: +m[1], minor: +m[2], patch: +m[3], pre: toPre(m[4]) } : null
}

export const formatVersion = (v: SemVer) => `${v.major}.${v.minor}.${v.patch}${v.pre.length ? `-${v.pre.join(".")}` : ""}`

function comparePre(a: SemVer["pre"], b: SemVer["pre"]) {
  if (!a.length || !b.length) return a.length ? -1 : b.length ? 1 : 0
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const [x, y] = [a[i], b[i]]
    if (x === undefined || y === undefined) return x === undefined ? -1 : 1
    if (x === y) continue
    if (typeof x === "number" && typeof y === "number") return x < y ? -1 : 1
    if (typeof x === "number" || typeof y === "number") return typeof x === "number" ? -1 : 1
    return x < y ? -1 : 1
  }
  return 0
}

/** Semver precedence: negative when a < b. */
export function compareVersions(a: SemVer, b: SemVer) {
  return a.major - b.major || a.minor - b.minor || a.patch - b.patch || comparePre(a.pre, b.pre)
}

const v = (major: number, minor: number, patch: number, pre: SemVer["pre"] = []): SemVer => ({ major, minor, patch, pre })
/** "<2.0.0-0": below every 2.0.0 prerelease, as npm writes upper bounds. */
const below = (major: number, minor: number, patch: number): Comparator => ({
  op: "<",
  version: v(major, minor, patch, [0]),
})
const ANY: ComparatorSet = [{ op: ">=", version: v(0, 0, 0) }]
const NOTHING: ComparatorSet = [{ op: "<", version: v(0, 0, 0, [0]) }]

function partial(text: string) {
  const m = PARTIAL.exec(text)
  if (!m) return null
  const num = (s?: string) => (s === undefined || /^[xX*]$/.test(s) ? null : Number(s))
  const [major, minor, patch] = [num(m[1]), num(m[2]), num(m[3])]
  // "1.x.3" is not valid: once a part is wild, the rest must be too.
  if ((major === null && (minor !== null || patch !== null)) || (minor === null && patch !== null)) return null
  return { major, minor, patch, pre: toPre(m[4]) }
}

/** Desugars one token (^1.2.3, ~1.2, >=1, 1.x, 1.2.3) into primitive comparators. */
function desugar(token: string): ComparatorSet | null {
  const m = /^(\^|~>?|>=|<=|>|<|=)?\s*(.*)$/.exec(token)
  if (!m) return null
  const op = m[1] ?? ""
  const p = partial(m[2])
  if (!p) return null
  const { major: M, minor: m2, patch: pa, pre } = p
  if (M === null) return op === ">" || op === "<" ? NOTHING : ANY
  if (op === "^") {
    const lower: Comparator = {
      op: ">=",
      version: v(M, m2 ?? 0, pa ?? 0, pre),
    }
    if (M > 0 || m2 === null) return [lower, below(M + 1, 0, 0)]
    if (m2 > 0 || pa === null) return [lower, below(0, m2 + 1, 0)]
    return [lower, below(0, 0, pa + 1)]
  }
  if (op.startsWith("~")) {
    const lower: Comparator = {
      op: ">=",
      version: v(M, m2 ?? 0, pa ?? 0, pre),
    }
    return [lower, m2 === null ? below(M + 1, 0, 0) : below(M, m2 + 1, 0)]
  }
  if (m2 !== null && pa !== null) return [{ op: (op || "=") as Op, version: v(M, m2, pa, pre) }]
  // A partial version stands for every version it covers: "1.2" is >=1.2.0 <1.3.0-0.
  const start = v(M, m2 ?? 0, 0)
  const next = m2 === null ? v(M + 1, 0, 0) : v(M, m2 + 1, 0)
  if (op === ">") return [{ op: ">=", version: next }]
  if (op === ">=") return [{ op: ">=", version: start }]
  if (op === "<") return [{ op: "<", version: { ...start, pre: [0] } }]
  if (op === "<=") return [{ op: "<", version: { ...next, pre: [0] } }]
  return [
    { op: ">=", version: start },
    { op: "<", version: { ...next, pre: [0] } },
  ]
}

/** Parses an npm range ("^1.2.3 || >=2 <3", "1.2 - 2", "~0.4") into OR'd comparator sets, or null if invalid. */
export function parseRange(range: string): ComparatorSet[] | null {
  const sets: ComparatorSet[] = []
  for (const alternative of range.split("||")) {
    const text = alternative.trim().replace(/(\^|~>?|>=|<=|>|<|=)\s+/g, "$1")
    const hyphen = /^(\S+)\s+-\s+(\S+)$/.exec(text)
    if (hyphen) {
      const [from, to] = [partial(hyphen[1]), partial(hyphen[2])]
      if (!from || !to) return null
      const lower = from.major === null ? ANY : desugar(`>=${hyphen[1]}`)
      const upper = to.major === null ? [] : desugar(`<=${hyphen[2]}`)
      if (!lower || !upper) return null
      sets.push([...lower, ...upper])
      continue
    }
    const set: ComparatorSet = []
    for (const token of text ? text.split(/\s+/) : ["*"]) {
      const parsed = desugar(token)
      if (!parsed) return null
      set.push(...parsed)
    }
    sets.push(set)
  }
  return sets
}

function passes(version: SemVer, { op, version: bound }: Comparator) {
  const c = compareVersions(version, bound)
  return op === "=" ? c === 0 : op === ">" ? c > 0 : op === ">=" ? c >= 0 : op === "<" ? c < 0 : c <= 0
}

/** True when the version satisfies the range. Prereleases only match a set that names the same x.y.z with a prerelease. */
export function satisfies(version: SemVer, sets: ComparatorSet[]) {
  return sets.some((set) => {
    if (!set.every((comparator) => passes(version, comparator))) return false
    if (!version.pre.length) return true
    return set.some(
      ({ version: b }) => b.pre.length > 0 && b.major === version.major && b.minor === version.minor && b.patch === version.patch,
    )
  })
}

export interface Bounds {
  lower?: { version: SemVer; inclusive: boolean }
  upper?: { version: SemVer; inclusive: boolean }
  empty: boolean
}

/** Collapses a comparator set to its tightest lower and upper bound. */
export function boundsOf(set: ComparatorSet): Bounds {
  let lower: Bounds["lower"]
  let upper: Bounds["upper"]
  for (const { op, version } of set) {
    if (op !== "<" && op !== "<=") {
      const c = lower ? compareVersions(version, lower.version) : 1
      if (c > 0 || (c === 0 && op === ">")) lower = { version, inclusive: op !== ">" }
    }
    if (op !== ">" && op !== ">=") {
      const c = upper ? compareVersions(version, upper.version) : -1
      if (c < 0 || (c === 0 && op === "<")) upper = { version, inclusive: op !== "<" }
    }
  }
  // With no lower bound, everything from 0.0.0-0 up counts, so "<0.0.0-0" is empty.
  const floor = lower ?? { version: v(0, 0, 0, [0]), inclusive: true }
  const c = upper ? compareVersions(floor.version, upper.version) : -1
  return {
    lower,
    upper,
    empty: c > 0 || (c === 0 && !(floor.inclusive && upper?.inclusive)),
  }
}

/** Shows an upper bound the way people think of it: "<2.0.0-0" reads as "2.0.0". */
const shown = (version: SemVer) =>
  formatVersion(version.pre.length === 1 && version.pre[0] === 0 ? { ...version, pre: [] } : version)

/** Plain-English reading of a parsed range: "1.2.3 up to but not including 2.0.0, or 3.0.0 or newer". */
export function describeRange(sets: ComparatorSet[]): string {
  const phrases = sets.map((set) => {
    const { lower, upper, empty } = boundsOf(set)
    if (empty) return "nothing"
    const from = lower && shown(lower.version)
    const to = upper && shown(upper.version)
    if (lower && upper) {
      const next = lower.version.pre.length ? null : { ...lower.version, patch: lower.version.patch + 1, pre: [0] }
      // ">=0.0.3 <0.0.4-0" admits only 0.0.3 among releases.
      const onlyOne = lower.inclusive && !upper.inclusive && next && compareVersions(next, upper.version) === 0
      if (from === to || onlyOne) return `exactly ${from}`
      if (lower.inclusive) return upper.inclusive ? `${from} through ${to}` : `${from} up to but not including ${to}`
      return upper.inclusive ? `anything above ${from} up to and including ${to}` : `anything above ${from} and below ${to}`
    }
    if (lower) return lower.inclusive ? (from === "0.0.0" ? "any version" : `${from} or newer`) : `anything newer than ${from}`
    return upper?.inclusive ? `${to} or older` : `anything below ${to}`
  })
  return [...new Set(phrases)].join(", or ")
}

/** Slips that parse but don't mean what was intended, or that stop parsing, each with an optional fix. */
export function findRangeSlips(range: string) {
  const slips: {
    kind: "and" | "hyphen" | "zero-minor" | "zero-patch"
    token: string
    fix?: string
  }[] = []
  if (/,|&&/.test(range))
    slips.push({
      kind: "and",
      token: range,
      fix: range.replace(/\s*(,|&&)\s*/g, " ").trim(),
    })
  for (const token of range.split(/\s+|\|\|/)) {
    // "1.2.3-2.0.0" is a prerelease of 1.2.3, not a range: npm needs spaces around the hyphen.
    const hyphen = /^v?(\d+\.\d+\.\d+)-(\d+\.\d+(?:\.\d+)?)$/.exec(token)
    if (hyphen)
      slips.push({
        kind: "hyphen",
        token,
        fix: range.replace(token, `${hyphen[1]} - ${hyphen[2]}`),
      })
    const zero = /^\^v?0\.(\d+|[xX*])(?:\.(\d+))?/.exec(token)
    if (zero && /^\d+$/.test(zero[1]) && Number(zero[1]) > 0) slips.push({ kind: "zero-minor", token })
    else if (zero && zero[1] === "0" && zero[2] !== undefined) slips.push({ kind: "zero-patch", token })
  }
  return slips
}

"use client"

// Bollard UI — version-range-input · MIT licence · https://bollard-ui.vercel.app/components/version-range-input

import * as React from "react"
import { Check, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  boundsOf,
  compareVersions,
  describeRange,
  findRangeSlips,
  formatVersion,
  parseRange,
  parseVersion,
  satisfies,
  type ComparatorSet,
  type SemVer,
} from "./semver"

export * from "./semver"

const fill = (template: string, values: Record<string, string>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => values[key] ?? match)

const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-mono font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

export interface VersionRangeInputProps extends Omit<
  React.ComponentProps<"input">,
  "value" | "defaultValue" | "onChange" | "type"
> {
  /** Visible label. */
  label?: string
  /** Controlled value. */
  value?: string
  /** Initial value when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every change. */
  onValueChange?: (value: string) => void
  /** Published versions to test the range against. Invalid entries are ignored. */
  versions?: string[]
  /** Pause in ms before warnings appear while typing. Leaving the field shows them at once. */
  delay?: number
  /** Turns a parsed range into words. Override to translate. */
  describe?: (sets: ComparatorSet[]) => string
  /** Templates: `{range}`, `{allowed}`, `{token}`, `{version}`, `{count}`, `{total}` are filled in. */
  allowsText?: string
  /** Count of matching versions. */
  matchCountText?: string
  /** Shown when the range can't be parsed. */
  invalidText?: string
  /** Warning when commas are used for AND. */
  andText?: string
  /** Warning for a hyphen range without spaces. */
  hyphenText?: string
  /** Warning for ^0.x ranges. */
  zeroMinorText?: string
  /** Warning for ^0.0.x ranges. */
  zeroPatchText?: string
  /** Shown when no published version matches. */
  noMatchText?: string
  /** Shown when the range can never match. */
  neverText?: string
  /** Shown when the latest version is outside the range. */
  latestOutsideText?: string
  /** Badge on the version a fresh install would resolve to. */
  installsLabel?: string
  /** Accessible label of a suggested-range fix button. */
  fixAriaLabel?: (fix: string) => string
  /** Accessible name of the published-versions list. */
  versionsLabel?: string
  /** Screen-reader note on each listed version. */
  matchSrText?: (matches: boolean) => string
}

/**
 * A semver range field (npm-style ^ ~ >= < x || and hyphen ranges) that reads
 * the range back in plain English, marks which published versions match and
 * which one a fresh install picks, and warns about the classic surprises:
 * ^0.x locking to one minor, "1.2.3-2.0.0" being a prerelease rather than a
 * range, commas for AND, and ranges that match nothing that exists.
 */
export function VersionRangeInput({
  label = "Version range",
  value,
  defaultValue = "",
  onValueChange,
  versions = [],
  delay = 500,
  describe = describeRange,
  allowsText = "{range} allows {allowed}.",
  matchCountText = "{count} of {total} published versions match",
  invalidText = "That isn't a valid range.",
  andText = "npm ranges use a space for AND, not a comma or &&.",
  hyphenText = "{token} is a prerelease of one version, not a range.",
  zeroMinorText = "{token} won't reach the next 0.x minor: below 1.0, every minor is treated as breaking.",
  zeroPatchText = "{token} allows only that one version: below 0.1, every patch is breaking.",
  noMatchText = "No published version matches.",
  neverText = "This range can never match any version.",
  latestOutsideText = "Excludes the latest, {version}.",
  installsLabel = "installs",
  id,
  fixAriaLabel = (fix) => `Use ${fix}`,
  versionsLabel = "Published versions",
  matchSrText = (matches) => (matches ? " matches" : " does not match"),
  className,
  onBlur,
  ref,
  ...props
}: VersionRangeInputProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [settled, setSettled] = React.useState(defaultValue)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const range = value ?? inner

  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)

  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(range), delay)
    return () => clearTimeout(timer)
  }, [range, delay])

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const apply = (next: string) => {
    update(next)
    setSettled(next)
    inputRef.current?.focus()
  }

  const published = React.useMemo(
    () =>
      versions
        .map((text) => parseVersion(text))
        .filter((v): v is SemVer => !!v)
        .sort(compareVersions),
    [versions],
  )
  const sets = React.useMemo(() => parseRange(range), [range])
  const ready = settled === range
  const matched = published.map((version) => !!sets && satisfies(version, sets))
  const installs = matched.lastIndexOf(true)
  const stable = published.filter((version) => !version.pre.length)
  const latest = stable[stable.length - 1]
  const never = !!sets && sets.every((set) => boundsOf(set).empty)
  const count = matched.filter(Boolean).length

  const lines: { key: string; text: string; fix?: string }[] = []
  if (ready) {
    for (const slip of findRangeSlips(range)) {
      const template = {
        and: andText,
        hyphen: hyphenText,
        "zero-minor": zeroMinorText,
        "zero-patch": zeroPatchText,
      }[slip.kind]
      lines.push({
        key: `${slip.kind}-${slip.token}`,
        text: fill(template, { token: slip.token }),
        fix: slip.fix,
      })
    }
    if (sets && never) lines.push({ key: "never", text: neverText })
    else if (sets && published.length && count === 0) {
      lines.push({
        key: "none",
        text: noMatchText,
        fix: latest ? `^${formatVersion(latest)}` : undefined,
      })
    }
  }
  const latestIndex = latest ? published.indexOf(latest) : -1
  const latestOutside = ready && sets && count > 0 && latestIndex >= 0 && !matched[latestIndex]

  return (
    <div data-slot="version-range-input" className={cn("grid w-full max-w-sm gap-1.5", className)}>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">
        {label}
      </label>
      <input
        ref={inputRef}
        id={inputId}
        type="text"
        autoComplete="off"
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={false}
        value={range}
        onChange={(event) => update(event.target.value)}
        onBlur={(event) => {
          setSettled(range)
          onBlur?.(event)
        }}
        aria-invalid={ready && !sets ? true : undefined}
        aria-describedby={`${inputId}-hint`}
        data-warning={lines.length && sets ? "" : undefined}
        className={fieldClass}
        {...props}
      />
      <div id={`${inputId}-hint`} aria-live="polite" className="grid min-h-6 gap-1 text-xs">
        {sets ? (
          <p className="py-1 text-muted-foreground">
            {fill(allowsText, {
              range: range.trim() || "*",
              allowed: describe(sets),
            })}
            {latestOutside && latest && <> {fill(latestOutsideText, { version: formatVersion(latest) })}</>}
          </p>
        ) : ready && range.trim() ? (
          <p role="alert" className="flex items-center gap-1.5 py-1 text-destructive">
            <TriangleAlert aria-hidden className="size-3.5 shrink-0" />
            {invalidText}
          </p>
        ) : null}
        {lines.map(({ key, text, fix }) => (
          <p key={key} className="flex gap-1.5 text-amber-700 dark:text-amber-400">
            <span className="flex h-6 shrink-0 items-center">
              <TriangleAlert aria-hidden className="size-3.5" />
            </span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
              <span className="py-1">{text}</span>
              {fix && (
                <button type="button" onClick={() => apply(fix)} aria-label={fixAriaLabel(fix)} className={fixClass}>
                  {fix}
                </button>
              )}
            </span>
          </p>
        ))}
      </div>
      {published.length > 0 && (
        <div className="grid gap-1.5">
          <p className="text-xs text-muted-foreground">
            {fill(matchCountText, {
              count: String(count),
              total: String(published.length),
            })}
          </p>
          <ul className="flex flex-wrap gap-1" aria-label={versionsLabel}>
            {published.map((version, index) => (
              <li
                key={formatVersion(version)}
                data-match={matched[index] || undefined}
                className={cn(
                  "inline-flex h-6 items-center gap-1 rounded-md border px-1.5 font-mono text-xs transition-colors duration-200 ease-out motion-reduce:transition-none",
                  matched[index]
                    ? "border-emerald-600/30 bg-emerald-500/10 text-emerald-800 dark:border-emerald-400/30 dark:text-emerald-300"
                    : "text-muted-foreground/70 line-through decoration-muted-foreground/40",
                )}
              >
                {matched[index] && <Check aria-hidden className="size-3" />}
                {formatVersion(version)}
                <span className="sr-only">{matchSrText(Boolean(matched[index]))}</span>
                {index === installs && (
                  <span className="rounded-sm bg-emerald-600 px-1 font-sans text-[10px] leading-4 font-medium text-white dark:bg-emerald-400 dark:text-emerald-950">
                    {installsLabel}
                  </span>
                )}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}
